cd /tmp/sv-df30edb2b73847ed9e55dcc3732650e8/moderate-msbuild-properties && dotnet package list --format json 2>/dev/null | python3 -c "
import sys, json
d = json.load(sys.stdin)
for p in d['projects']:
    name = p['path'].split('/')[-1]
    for fw in p['frameworks']:
        for pkg in fw['topLevelPackages']:
            print(f'{name} | {pkg[\"id\"]} | {pkg[\"resolvedVersion\"]}')
"

